public static async Task<string?> ReadFrameAsync(Stream stream, CancellationToken cancellationToken)
{
    byte[] prefix = new byte[4];
    int prefixRead = 0;
    while (prefixRead < 4)
    {
        cancellationToken.ThrowIfCancellationRequested();
        int read = await stream.ReadAsync(prefix.AsMemory(prefixRead, 4 - prefixRead), cancellationToken).ConfigureAwait(false);
        if (read == 0)
        {
            if (prefixRead == 0)
                return null;
            throw new EndOfStreamException();
        }
        prefixRead += read;
    }

    int length = (prefix[0] << 24) | (prefix[1] << 16) | (prefix[2] << 8) | prefix[3];

    if (length > 1024 * 1024)
        throw new InvalidDataException("Frame length exceeds 1 MiB limit.");

    if (length == 0)
        return string.Empty;

    byte[] payload = new byte[length];
    int payloadRead = 0;
    while (payloadRead < length)
    {
        cancellationToken.ThrowIfCancellationRequested();
        int read = await stream.ReadAsync(payload.AsMemory(payloadRead, length - payloadRead), cancellationToken).ConfigureAwait(false);
        if (read == 0)
            throw new EndOfStreamException();
        payloadRead += read;
    }

    try
    {
        return Encoding.UTF8.GetString(payload);
    }
    catch (ArgumentException)
    {
        throw new InvalidDataException("Invalid UTF-8 encoding in frame payload.");
    }
}
